#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

int n, m;
vector<ll> players, points;

// Greedy: players from left to right take the leftmost uncollected points they can.
bool feasible(ll time) {
    int first = 0;
    for (ll player : players) {
        if (first == m) return true;
        ll point = points[first];
        if (point < player - time) return false;  // no player can reach it any more
        if (point > player + time) continue;
        ll reach;
        if (point <= player) {
            ll leftDistance = player - point;
            while (first < m && points[first] <= player) first++;
            // Go left first then right, or go right first then come back left.
            reach = max(player + time - 2 * leftDistance, player + (time - leftDistance) / 2);
        } else {
            reach = player + time;
        }
        while (first < m && points[first] <= reach) first++;
    }
    return first == m;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n >> m;
    players.resize(n), points.resize(m);
    for (auto &x : players) cin >> x;
    for (auto &x : points) cin >> x;
    sort(players.begin(), players.end());
    sort(points.begin(), points.end());
    ll low = 0, high = 2000000001;
    while (low < high) {
        ll mid = (low + high) / 2;
        if (feasible(mid)) high = mid;
        else low = mid + 1;
    }
    cout << low << "\n";
}

import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    static int n, m;
    static long[] players, points;

    static boolean feasible(long time) {
        int first = 0;
        for (long player : players) {
            if (first == m) return true;
            long point = points[first];
            if (point < player - time) return false;
            if (point > player + time) continue;
            long reach;
            if (point <= player) {
                long leftDistance = player - point;
                while (first < m && points[first] <= player) first++;
                reach = Math.max(player + time - 2 * leftDistance, player + (time - leftDistance) / 2);
            } else {
                reach = player + time;
            }
            while (first < m && points[first] <= reach) first++;
        }
        return first == m;
    }

    public static void main(String[] args) throws IOException {
        n = nextInt();
        m = nextInt();
        players = new long[n];
        points = new long[m];
        for (int i = 0; i < n; i++) players[i] = nextLong();
        for (int i = 0; i < m; i++) points[i] = nextLong();
        Arrays.sort(players);
        Arrays.sort(points);
        long low = 0, high = 2000000001;
        while (low < high) {
            long mid = (low + high) / 2;
            if (feasible(mid)) high = mid;
            else low = mid + 1;
        }
        System.out.print(low + "\n");
    }
}

package main

import (
	"io"
	"os"
	"slices"
	"strconv"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

var players, points []int

// feasible lets players from left to right take the leftmost uncollected points they can.
func feasible(time int) bool {
	first, m := 0, len(points)
	for _, player := range players {
		if first == m {
			return true
		}
		point := points[first]
		if point < player-time {
			return false
		}
		if point > player+time {
			continue
		}
		reach := player + time
		if point <= player {
			leftDistance := player - point
			for first < m && points[first] <= player {
				first++
			}
			reach = max(player+time-2*leftDistance, player+(time-leftDistance)/2)
		}
		for first < m && points[first] <= reach {
			first++
		}
	}
	return first == m
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, m := nextInt(), nextInt()
	players, points = make([]int, n), make([]int, m)
	for i := range players {
		players[i] = nextInt()
	}
	for i := range points {
		points[i] = nextInt()
	}
	slices.Sort(players)
	slices.Sort(points)
	low, high := 0, 2000000001
	for low < high {
		mid := (low + high) / 2
		if feasible(mid) {
			high = mid
		} else {
			low = mid + 1
		}
	}
	os.Stdout.WriteString(strconv.Itoa(low) + "\n")
}
